create or replace function public.complete_learning_lesson(p_idempotency_key text,p_lesson_id text,p_progress_percent integer,p_last_position_seconds integer) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$declare v_user uuid:=auth.uid();v_response jsonb;begin if v_user is null then raise exception 'unauthenticated';end if;if char_length(p_idempotency_key)<8 or p_progress_percent not between 0 and 100 or p_last_position_seconds<0 then raise exception 'invalid input';end if;select response_snapshot into v_response from public.idempotency_records where user_id=v_user and operation='complete_lesson' and idempotency_key=p_idempotency_key and status='completed';if found then return v_response;end if;insert into public.idempotency_records(user_id,operation,idempotency_key,status,expires_at) values(v_user,'complete_lesson',p_idempotency_key,'processing',now()+interval '7 days') on conflict do nothing;insert into public.learning_progress(user_id,lesson_id,status,progress_percent,last_position_seconds,started_at,completed_at) values(v_user,p_lesson_id,case when p_progress_percent=100 then 'completed' else 'in_progress' end,p_progress_percent,p_last_position_seconds,now(),case when p_progress_percent=100 then now() end) on conflict(user_id,lesson_id) do update set status=excluded.status,progress_percent=greatest(public.learning_progress.progress_percent,excluded.progress_percent),last_position_seconds=greatest(public.learning_progress.last_position_seconds,excluded.last_position_seconds),completed_at=coalesce(public.learning_progress.completed_at,excluded.completed_at),updated_at=now();v_response=jsonb_build_object('lessonId',p_lesson_id,'progress',p_progress_percent);insert into public.transactional_outbox(aggregate_type,aggregate_id,event_type,payload) values('learner',v_user::text,'learning.lesson_completed',v_response||jsonb_build_object('userId',v_user));update public.idempotency_records set status='completed',response_snapshot=v_response where user_id=v_user and operation='complete_lesson' and idempotency_key=p_idempotency_key;return v_response;end$$;

create or replace function public.complete_interview_session(p_idempotency_key text,p_target_role_slug text,p_language text,p_responses jsonb,p_score_summary jsonb) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$declare v_user uuid:=auth.uid();v_session uuid;v_response jsonb;begin if v_user is null then raise exception 'unauthenticated';end if;if char_length(p_idempotency_key)<8 or p_language not in('en','hi') or jsonb_array_length(p_responses) not between 1 and 20 then raise exception 'invalid input';end if;select response_snapshot into v_response from public.idempotency_records where user_id=v_user and operation='complete_interview' and idempotency_key=p_idempotency_key and status='completed';if found then return v_response;end if;insert into public.idempotency_records(user_id,operation,idempotency_key,status,expires_at) values(v_user,'complete_interview',p_idempotency_key,'processing',now()+interval '7 days') on conflict do nothing;insert into public.interview_sessions(user_id,target_role_slug,language,status,question_count,score_summary,completed_at) values(v_user,p_target_role_slug,p_language,'completed',jsonb_array_length(p_responses),p_score_summary,now()) returning id into v_session;insert into public.interview_responses(session_id,position,question_text,answer_text,ai_feedback,prompt_version) select v_session,(x->>'position')::smallint,x->>'questionText',x->>'answerText',x->>'aiFeedback','interviewer-v2' from jsonb_array_elements(p_responses)x;v_response=jsonb_build_object('sessionId',v_session);insert into public.transactional_outbox(aggregate_type,aggregate_id,event_type,payload) values('interview_session',v_session::text,'interview.completed',v_response||jsonb_build_object('userId',v_user));update public.idempotency_records set status='completed',response_snapshot=v_response where user_id=v_user and operation='complete_interview' and idempotency_key=p_idempotency_key;return v_response;end$$;

create or replace function public.submit_evidence_metadata(p_idempotency_key text,p_skill_slug text,p_title text,p_description text,p_storage_paths text[]) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$declare v_user uuid:=auth.uid();v_evidence uuid;v_response jsonb;begin if v_user is null then raise exception 'unauthenticated';end if;if char_length(p_idempotency_key)<8 or cardinality(p_storage_paths) not between 1 and 4 then raise exception 'invalid input';end if;if exists(select 1 from unnest(p_storage_paths)p where split_part(p,'/',1)<>v_user::text) then raise exception 'invalid storage owner';end if;select response_snapshot into v_response from public.idempotency_records where user_id=v_user and operation='submit_evidence' and idempotency_key=p_idempotency_key and status='completed';if found then return v_response;end if;insert into public.idempotency_records(user_id,operation,idempotency_key,status,expires_at) values(v_user,'submit_evidence',p_idempotency_key,'processing',now()+interval '7 days') on conflict do nothing;insert into public.skill_evidence(user_id,skill_slug,evidence_type,title,description,storage_path,verification_status,submission_metadata) values(v_user,p_skill_slug,'project',p_title,p_description,p_storage_paths[1],'pending',jsonb_build_object('additional_paths',p_storage_paths[2:cardinality(p_storage_paths)],'rubric_slug','wiring-board-v1')) returning id into v_evidence;v_response=jsonb_build_object('evidenceId',v_evidence);insert into public.transactional_outbox(aggregate_type,aggregate_id,event_type,payload) values('skill_evidence',v_evidence::text,'evidence.submitted',v_response||jsonb_build_object('userId',v_user));update public.idempotency_records set status='completed',response_snapshot=v_response where user_id=v_user and operation='submit_evidence' and idempotency_key=p_idempotency_key;return v_response;end$$;

revoke all on function public.complete_learning_lesson(text,text,integer,integer) from public;grant execute on function public.complete_learning_lesson(text,text,integer,integer) to authenticated;
revoke all on function public.complete_interview_session(text,text,text,jsonb,jsonb) from public;grant execute on function public.complete_interview_session(text,text,text,jsonb,jsonb) to authenticated;
revoke all on function public.submit_evidence_metadata(text,text,text,text,text[]) from public;grant execute on function public.submit_evidence_metadata(text,text,text,text,text[]) to authenticated;
